import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"42、【益】 震下巽上","description":"周易口訣義 - 42、【益】 震下巽上","frontmatter":{"title":"42、【益】 震下巽上","description":"周易口訣義 - 42、【益】 震下巽上"},"headers":[],"relativePath":"classics/koujueyi/044.md","filePath":"classics/koujueyi/044.md"}'),r={name:"classics/koujueyi/044.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_42、【益】-震下巽上" tabindex="-1">42、【益】 震下巽上 <a class="header-anchor" href="#_42、【益】-震下巽上" aria-label="Permalink to “42、【益】 震下巽上”">​</a></h1><p>彖曰：益，損上益下，民說無疆。自上下下，其道大光。「利有攸往」，中正有慶。「利涉大川」，木道乃行。益動而巽，日進無疆。天施地生，其益無方。凡益之道，與時偕行。</p><p>象曰：風雷，益。君子以見善則遷，有過則改。</p><p>初九：利用為大作，元吉，無咎。</p><p>象曰：「元吉無咎」，下不厚事也。</p><p>六二：或益之十朋之龜，弗克違，永貞吉。王用享於帝，吉。</p><p>象曰：「或益之」，自外來也。</p><p>六三：益之用凶事，無咎。有孚中行，告公用圭。</p><p>象曰：益用凶事，固有之也。</p><p>六四：中行告公從，利用為依遷國。</p><p>象曰：「告公從」，以益志也。</p><p>九五：有孚惠心，勿問，元吉。有孚惠我德。象曰：「有孚惠心」，勿問之矣；「惠我德」，大得志也。</p><p>上九：莫益之，或擊之，立心勿恆，兇。</p><p>象曰：「莫益之」，偏辭也；「或擊之」，自外來也。</p><p>解讀</p><p>益「利有攸往」者，益是增長之名，饒裕為義也。損卦損下益上，益卦損上益下者，亦猶人君能自損己而惠下人。故宋衷雲：「明君之德，必須損己而利人，則下盡益矣。」君能以益物為意，動而無有違者，即斯而往，何所不利？故曰「利有攸往」也。利涉大川者，能益於物，則理絕難險，故「利涉大川」也。象曰「風雷，益」者，雷以發生，風能長育，萬物皆益，故益之為義，在雷風也。君子以見善則遷，有過則改。遷，進移也；改，更懲也。君子求益，莫過遷進，企慕道德，其有過惡，改更懲戒，不再為也。</p><p>初九「利用為大作，元吉，無咎」者，處益之初，應巽之始，體剛乾事，能堪建大事之端，以成王事者也。然雖有其才而得其時，不居其位，即時人不輔，欲有興作，即禍必生焉，必須有大功以補其過，即得無咎，故曰「元吉，無咎」。元吉是有功之詞，「大作」謂興作大事也。</p><p>六二或益之十朋之龜，弗克違，永貞吉。王用享於帝，吉者，以柔居中，又應於巽，處益而懷巽，即物皆歸焉，故曰「或益之」。朋，眾也；龜，靈鑑也。六二既懷謙沖，即物自外來，朋靈獻策，群才響應，故「十朋之龜，弗克違」也。然位不當尊，故「永貞吉」也。處益如斯，上下歸德，故王用此時，可以享獻天帝，即朋靈降福，故曰「王用享於帝，吉」也。</p><p>六三，益之用凶事，無咎。「有孚中行，告公用圭」者，以陰居陽，以剛健而求於益，故曰「益之」。不能行謙而用剛壯求益，即物所不與。若以謙讓責之，理合誅討；若以意測，原本情，志在救難，即物皆恃之，是「用凶事」而得免咎，故曰「用凶事，無咎」也。若乃求益不為私己，志在救難，用壯不至剛暴，斯乃適合時宜，是有信實而得中行，此中行之道，執圭以告於公，救兇危之事，故曰「有孚中行，告公用圭」也。</p><p>六四，「中行告公從，利用為依遷國」者，以柔處臣位，居巽之初，在上應下，位雖不中，用中而行，故曰「中行」。與君相近，即是藩屏之臣。以此中行之道而告於公，公必從之。以此道依人而遷，國人無不順；明以中行之道而遷國，人無不利矣，故曰「利用為依遷國」也。</p><p>九五：有孚惠心，勿問元吉。「有孚惠我德」者，得位處尊，為益之主，兼張德義。德義之本，莫盛乎信；為益之大，莫大於心，因人所欲而己。與人有信有惠，盡物之心，益之盛矣。既有斯德，必獲大吉，不假疑問，德必昭彰，故曰「有孚惠心，勿問元吉」。我既以信惠被於物，則天下皆以信惠歸我，故「有孚惠我德」也。</p><p>上九：莫益之，或擊之，立心勿恆，兇者，處益之極，益之甚也。既已過盈，即人之不與，故曰「莫益之」也。無厭之求，怨怒非一，故曰「或擊之」也。勿，無也。益以過極而更有求，是立心無恆，兇禍必至，故曰「立心勿恆，兇」也。周易口訣義卷四，</p>',22)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
